537		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
538			t.Fatal(err)
539		}
540		sid := mustSell(t, e, "A", 5, 10)
541	
542		// 制造缺口：seq3 先到。
543		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 10}, 0)
544	
545		// 缺口期间：买单拒绝，但卖单、撤单、已有订单成交均可处理。
546		if _, err := e.Buy("A", 1, 10); err == nil {
