		hypoPos = st.position + t.Qty
	} else {
		hypoCash = e.cash + amount
		hypoPos = st.position - t.Qty
	}
	if _, _, ok := e.valuationHypoLocked(hypoCash, o.Symbol, hypoPos, true, Quote{}, false); !ok {
