	// 按合约排序、序号/时刻/价格俱全。
	if rec.RiskQuoteRefs[0] != (RiskQuoteRef{Symbol: "A", Seq: 2, Moment: 9, Price: 1}) {
		t.Fatalf("A 报价定位错误: %+v", rec.RiskQuoteRefs[0])
	}
